import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"快速面板设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/quick-panel.md","filePath":"zh-CN/user-guide/settings/quick-panel.md","lastUpdated":1790961642000}'),n={name:"zh-CN/user-guide/settings/quick-panel.md"};function l(i,t,a,g,d,c){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="快速面板设置" tabindex="-1">快速面板设置 <a class="header-anchor" href="#快速面板设置" aria-label="Permalink to &quot;快速面板设置&quot;">​</a></h1><p><strong>快速面板（Quick Panel）</strong> 是 Lertaro 专为高频文件取用、项目上下文管理与桌面拖拽交互打造的浮动工作区。它会在按下快捷键时自动停靠在当前前台活动窗口的右下角，让你无需离开当前工作窗口即可快速浏览、拖入或分发常用文件。</p><h2 id="_1-核心机制与总开关" tabindex="-1">1. 核心机制与总开关 <a class="header-anchor" href="#_1-核心机制与总开关" aria-label="Permalink to &quot;1. 核心机制与总开关&quot;">​</a></h2><ul><li><strong>启用快速面板</strong>：总开关，关闭后将不再监听呼出快捷键。</li><li><strong>唤起快捷键</strong>：默认快捷键为 <strong><code>Ctrl+F2</code></strong>（可在<a href="./hotkeys-page.html"><strong>设置 → 快捷键</strong></a>中自定义）。</li><li><strong>智能贴靠与尺寸约束</strong>：面板默认尺寸为宿主窗口宽高的各二分之一（最小尺寸限制为 <code>280 × 200px</code>，确保内容与筛选框完整可用）。若当前处于 Lertaro 自身窗口时按快捷键会被安全忽略，防止窗口重叠；面板打开状态下再次按下同款快捷键可一键关闭。</li><li><strong>快速跳转联动</strong>：面板打开期间，当前选中分组所指向的物理目录会被自动记录为活动目录。在任意系统文件对话框中按下快速跳转快捷键（默认 <code>Ctrl+G</code>），即可直接跳转到该目录。</li></ul><h2 id="_2-工作区-workspaces" tabindex="-1">2. 工作区（Workspaces） <a class="header-anchor" href="#_2-工作区-workspaces" aria-label="Permalink to &quot;2. 工作区（Workspaces）&quot;">​</a></h2><p>工作区用于按项目或任务组织一组相关的文件夹来源：</p><ul><li><strong>工作区列表管理</strong>：左侧列表呈现已创建的工作区，支持<strong>新建工作区</strong>、<strong>复制工作区</strong>与<strong>删除工作区</strong>，可通过拖拽左侧手柄调整其在面板标签栏中的前后排列顺序。</li><li><strong>工作区属性</strong>： <ul><li><strong>名称</strong>：标签页显示的文本（留空时将自动使用跟随系统语言的默认名称）。</li><li><strong>启用开关</strong>：勾选状态决定是否在面板标签栏中显示。在面板中点击标签上的 <strong>×</strong> 按钮即是将该工作区临时隐藏，可在此处重新勾选恢复。</li></ul></li></ul><p>选中的工作区可通过右侧的两个子标签进行精细化配置：<strong>来源</strong>与<strong>应用</strong>。</p><h2 id="_3-来源配置-sources" tabindex="-1">3. 来源配置（Sources） <a class="header-anchor" href="#_3-来源配置-sources" aria-label="Permalink to &quot;3. 来源配置（Sources）&quot;">​</a></h2><p>每个来源代表工作区内部的一个独立内容分组：</p><ul><li><strong>添加文件夹</strong>：点击<strong>添加文件夹</strong>按钮选择物理目录。</li><li><strong>显示模式（Display Mode）</strong>： <ul><li><strong>最近改动的文件</strong> —— 由内存索引毫秒级直接应答，仅展示近期发生变动的文件（最新排在最前）。</li><li><strong>全部内容，最新在前</strong> —— 呈现全部文件，按修改时间降序排列。</li><li><strong>全部内容，按名称</strong> —— 适合作为固定文件的快捷工具栏。</li></ul></li><li><strong>包含子文件夹</strong>：开启后将递归收录其所有子目录下的文件。</li><li><strong>接受拖入的文件</strong>：开启后，支持直接从外部将文件、文件夹或浏览器图片拖入该分组，Lertaro 会自动调用 Windows 原生复制接口将文件复制进该目录（具备冲突提示与撤销支持）。</li><li><strong>文件过滤规则</strong>：可使用通配符或搜索语法中的 <code>@</code> 过滤器限制该分组展示的文件类型（例如 <code>*.mp4;*.mkv</code>、<code>*.lnk;:@doc;:@img</code> 或 <code>*.lnk;:@doc|img</code>）。</li><li><strong>最大条数与时间限制</strong>：可限制最大展示数量（设为 0 表示不限制）及仅展示若干分钟内改动过的文件。</li><li><strong>明细列表 vs 缩略图平铺</strong>：支持按分组独立选择以列表形式还是缩略图网格平铺展示（平铺时自动等比拉伸并保持画面原始比例）。</li></ul><h2 id="_4-插件标签-plugin-tabs" tabindex="-1">4. 插件标签（Plugin Tabs） <a class="header-anchor" href="#_4-插件标签-plugin-tabs" aria-label="Permalink to &quot;4. 插件标签（Plugin Tabs）&quot;">​</a></h2><p>除自定义工作区外，插件亦可直接向快速面板注册全局动态清单。CoreExtensions 核心插件内置了五个实用标签：</p><table tabindex="0"><thead><tr><th style="text-align:left;">插件标签</th><th style="text-align:left;">内容说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>收藏夹</strong></td><td style="text-align:left;">集中展示你的星标收藏项目，网址点击后在浏览器中打开。</td></tr><tr><td style="text-align:left;"><strong>历史记录</strong></td><td style="text-align:left;">展示你通过 Lertaro 打开过的最近项目与应用程序。</td></tr><tr><td style="text-align:left;"><strong>Windows 历史记录</strong></td><td style="text-align:left;">自动解析 Windows 系统级的“最近使用的文档”并列出真实物理文件。</td></tr><tr><td style="text-align:left;"><strong>上次目录</strong></td><td style="text-align:left;">自动追踪并递回你在资源管理器或文件对话框中刚刚离开的目录。</td></tr><tr><td style="text-align:left;"><strong>最近文件</strong></td><td style="text-align:left;">由后台内存索引直接汇总呈现所有配置目录下的最新变动文件。</td></tr></tbody></table><p>可在列表右侧独立控制各插件标签的显示状态以及采用平铺还是列表视图。</p><h2 id="_5-应用绑定与独立黑名单" tabindex="-1">5. 应用绑定与独立黑名单 <a class="header-anchor" href="#_5-应用绑定与独立黑名单" aria-label="Permalink to &quot;5. 应用绑定与独立黑名单&quot;">​</a></h2><ul><li><strong>应用关联（Applications）</strong>：可为工作区指定一个或多个前台进程名（如 <code>chrome.exe</code> 或 <code>devenv.exe</code>）。当你在该软件上呼出快速面板时，面板将自动直达该关联工作区，免去手动切标签的麻烦。</li><li><strong>仅快速面板黑名单</strong>：可在此配置不希望被快速面板打扰的进程名单。该名单会<strong>叠加</strong>在全局快捷键黑名单之上，专用于处理不希望被面板遮挡但无需全局禁用的特殊程序。</li></ul><h2 id="_6-面板交互指南" tabindex="-1">6. 面板交互指南 <a class="header-anchor" href="#_6-面板交互指南" aria-label="Permalink to &quot;6. 面板交互指南&quot;">​</a></h2><ul><li><strong>即时模糊过滤</strong>：面板右上角内置搜索过滤框，支持 fzf 模糊匹配与拼音别名，输入即可即时筛选当前工作区。它只按<strong>名称</strong>过滤，也绝不会重排列表顺序；某个分组的项目全部被筛掉时该分组会消失，但它的标签依然保留。<code>Escape</code> 先清空过滤词，只有<strong>第二次</strong>按 <code>Escape</code> 才关闭面板。</li><li><strong>全键盘流畅导航</strong>：使用上下方向键可无缝跨越不同分组连续滚动；在选中的条目上按下 <code>Enter</code> 键即可直接打开，面板保持展开。这一序列<strong>不</strong>循环：首个和末个可见条目就是硬边界，空分组会被跳过，而在尚未选中任何条目时 <code>↑</code> 与 <code>↓</code> 都落在第一个条目上。平铺视图下四个方向键改为沿视觉网格移动——<code>←</code>/<code>→</code> 遵循阅读顺序并跨越行边界，<code>↑</code>/<code>↓</code> 保持在同一列。</li><li><strong>标签快捷切换</strong>：按住 <code>Ctrl</code> + <code>1</code>–<code>9</code> 即可在各个工作区与插件标签间快速跳转。</li><li><strong>QuickLook 预览与钉住</strong>：选中条目后按 <code>Alt+P</code> 可在面板侧边呼出即时预览；按 <code>Ctrl+T</code>——或标题栏上的钉住按钮——可钉住面板使其在失去焦点时不自动消失。</li><li><strong>焦点落在哪里</strong>：呼出面板时光标会进入过滤框，且第一条条目已经处于选中状态，因此直接打字即可立刻收窄结果。只要该过滤框持有焦点，插件动作快捷键就会刻意让位——这里的 <code>Ctrl+A</code> 与 <code>Ctrl+C</code> 是文本编辑，不是文件操作。</li><li><strong>动作悬浮菜单</strong>：鼠标右键<strong>松开</strong>（而不是按下）时弹出与完整搜索窗口相同的动作悬浮菜单，并锚定在光标处，因此在一个尚未选中的行上点击右键就会作用于该行。此后 <code>↑ ↓ ← →</code>、<code>Enter</code>、<code>Space</code> 与 <code>Escape</code> 都交由该菜单接管。由于它的按键处理逻辑挂在面板上，菜单打开期间那些本来会关闭面板的点击空白处会被忽略。</li><li><strong>条目上的鼠标操作</strong>：双击左键直接打开；双击<strong>右键</strong>只会重新弹出悬浮菜单，绝不会启动项目。点击中键切换预览。指针悬停某个条目即会移动选中项。</li><li><strong>移动面板</strong>：指针靠近标题栏时，标题栏中会出现一条拖拽条，在那里拖动即可移动面板，而拖拽本身不会顺手把面板关掉（正因如此，从资源管理器拖出的文件才可能落进它里面）。</li><li><strong>点击空白处</strong>：焦点离开约 200 毫秒后面板隐藏；但以下几种情况它会暂不隐藏：你刚刚拖动过面板、面板已被钉住、动作悬浮菜单打开中，以及它呼出的预览正处于前台——点进自己的预览并不算点击空白处。</li><li><strong>调整选区</strong>：在某个分组内的空白处点击，会一次性清空<strong>所有</strong>分组的选中状态（按住 <code>Ctrl</code> 或 <code>Shift</code> 时除外）。框选只在其起始的分组内进行，<code>Ctrl</code> 可让选区累加；起于某一分组的框选不会伸进另一个分组。</li><li><strong>接受拖入的文件</strong>：<strong>起点在 Lertaro 内部</strong>的拖拽一律不被接受，因此半途而废的拖出不会变成一次多余的复制。又因为面板会因点击空白处而关闭，只有面板处于<strong>钉住</strong>状态时才能从资源管理器把文件拖进来。放下永远是复制，绝不是移动。</li><li><strong>分组标题</strong>：点击标题上的名称、路径或规则行即可折叠与展开该分组；排序与视图是它旁边的两个独立按钮。排序方式、视图模式与折叠状态只在本次会话有效，而标签页顺序与关闭标签页则会持久保存。</li></ul>',19)])])}const p=o(n,[["render",l]]);export{h as __pageData,p as default};
